import uuid
from sqlalchemy.orm import Session
from app.db.session import SessionLocal, engine, Base
from app.models import Category, Quiz, Question, Answer, QuizLevel, QuizStatus

Base.metadata.create_all(bind=engine)


# =============================================================================
# HELPER
# =============================================================================

def seed_category(db, data):
    name = data["category"]["name"]
    cat = db.query(Category).filter(Category.name == name).first()
    if cat:
        print(f"✓ Catégorie '{name}' existe déjà")
    else:
        cat = Category(id=str(uuid.uuid4()), name=name, description=data["category"]["description"], icon_url=data["category"]["icon_url"], is_active=True)
        db.add(cat)
        db.commit()
        print(f"✓ Catégorie '{name}' créée (ID: {cat.id})")

    for level_name, quiz_data in data["quizzes"].items():
        qz = db.query(Quiz).filter(Quiz.category_id == cat.id, Quiz.level == quiz_data["level"]).first()
        if qz:
            print(f"  ✓ Quiz '{qz.title}' existe déjà")
        else:
            qz = Quiz(id=str(uuid.uuid4()), category_id=cat.id, title=quiz_data["title"], level=quiz_data["level"], status=quiz_data["status"])
            db.add(qz)
            db.commit()
            print(f"  ✓ Quiz '{qz.title}' créé")

        for q_i, qdata in enumerate(quiz_data["questions"], 1):
            existing_q = db.query(Question).filter(Question.quiz_id == qz.id, Question.order == q_i).first()
            if existing_q:
                q = existing_q
            else:
                q = Question(id=str(uuid.uuid4()), quiz_id=qz.id, question_text=qdata["text"], order=q_i)
                db.add(q)
                db.commit()
                print(f"    ✓ Question {q_i} ajoutée")

            for a_i, adata in enumerate(qdata["answers"], 1):
                if not db.query(Answer).filter(Answer.question_id == q.id, Answer.order == a_i).first():
                    db.add(Answer(id=str(uuid.uuid4()), question_id=q.id, answer_text=adata["text"], is_correct=adata["is_correct"], order=a_i))
            if not existing_q:
                db.commit()


